  'speech.mediaTranscripts': "Ubah suara video menjadi teks",
  'speech.mediaTranscriptsLocal': "Saat AI membaca berkas video atau audio (misalnya rekaman rapat), server ini mengubah suaranya menjadi teks. Suara tidak pernah keluar dari server. Suara diproses per {sec} detik: satu kali baca mengubah sebanyak yang sempat, dan membaca lagi melanjutkan dari sana.",
  'speech.mediaTranscriptsSmall': "Nonaktif secara bawaan: server ini punya {cores} inti CPU, jadi mengubah suara menjadi teks memakan waktu lama. Admin dapat mengaktifkannya; saat nonaktif, AI tetap melihat cuplikan video.",
  'speech.mediaTranscriptsSpeedMin': "Diukur di server ini: sekitar {n} menit untuk setiap menit suara.",
  'speech.mediaTranscriptsSpeedSec': "Diukur di server ini: sekitar {n} detik untuk setiap menit suara.",
  'speech.mediaTranscriptsHosted': "Di server hosting ini satu kali baca mengubah paling banyak {min} menit suara baru menjadi teks.",
  'speech.mediaTranscriptsOpenRouter': "Saat AI membaca berkas video atau audio (rekaman rapat, panggilan pelanggan, video pelatihan), suaranya dikirim ke OpenRouter dan penyedianya untuk diubah menjadi teks. Ini materi yang berbeda dari input suara. Retensi data nol diminta, tetapi kami tidak dapat memaksakannya. Tidak ada yang dikirim dari percakapan rahasia.",
  'speech.privacy': "Audio dikirim ke OpenRouter dan penyedianya; retensi data nol diminta.",
  'speech.model': "Model",
  'speech.key': "Kunci API OpenRouter",
  'speech.keySet': "Kunci sudah diatur (…{hint}).",
  'speech.keyNone': "Belum ada kunci. Input suara tetap nonaktif sampai kunci ditambahkan.",
  'speech.getKey': "Dapatkan kunci di openrouter.ai/keys",
  'speech.price': "Biaya OpenRouter sekitar $0.1 per jam rekaman.",
  'speech.saveKey': "Simpan kunci",
  'speech.removeKey': "Hapus kunci",
  'speech.removeConfirm': "Hapus kunci OpenRouter? Input suara berhenti sampai kunci baru ditambahkan.",
  'speech.keySaved': "Kunci disimpan",
  'speech.keyRemoved': "Kunci dihapus",
  'speech.mediaTranscriptsHostedKey': "Saat AI membaca berkas video atau audio (misalnya rekaman rapat), transkripsi hosting Trina mengubah suaranya menjadi teks: suara dikirim lewat OpenRouter ke DeepInfra di AS (Groq jika DeepInfra tidak tersedia), dan keduanya tidak menyimpan data. Ini memakai jam gratis yang sama dengan input suara. Tidak ada yang dikirim dari percakapan rahasia.",
  'speech.privacyHosted': "Suara dikirim lewat OpenRouter ke DeepInfra di AS (Groq jika DeepInfra tidak tersedia) untuk diubah menjadi teks, dan hanya ke penyedia yang tidak menyimpan data (retensi data nol).",
  'speech.hostedKeyInUse': "Mentranskripsi dengan kunci dari hosting Trina. Kunci tim yang Anda tambahkan dipakai lebih dulu dan tanpa batas waktu (OpenRouter menagih akun tim).",
  'speech.hostedUsage': "Bulan ini: {used} dari {free} jam transkripsi gratis terpakai",
  'speech.hostedOwnKey': "Mentranskripsi dengan kunci tim, jadi jam gratis tidak terpakai.",
  'speech.removeConfirmHosted': "Hapus kunci OpenRouter tim? Setelah itu transkripsi memakai kunci hosting Trina, dalam jam gratis bulan ini.",
